"""Build the public static documentation from versioned playbook evidence. No dependencies."""
from pathlib import Path
from html import escape
from html.parser import HTMLParser
import json,re,shutil
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'_site'
if OUT.exists():shutil.rmtree(OUT)
OUT.mkdir();(OUT/'.nojekyll').touch();(OUT/'assets').mkdir();(OUT/'downloads').mkdir()
REPO='https://github.com/engeneon/anubis-blue'
scenarios=json.loads((ROOT/'tests/fixtures/architecture-scenarios.json').read_text())
selected=[s for s in scenarios if s['id'] in ['S11','S13','S14','S16']]
css='''*{box-sizing:border-box}body{margin:0;color:#183543;background:#f5f8fa;font:17px/1.65 system-ui,sans-serif}a{color:#075b78;text-underline-offset:3px}a:hover{color:#963d14}header{background:#102d3b;color:white;padding:18px max(20px,calc((100% - 1120px)/2));}header a{color:white}nav{display:flex;gap:12px 22px;flex-wrap:wrap}nav a[aria-current=page]{text-decoration-thickness:3px}.brand{display:flex;gap:14px;align-items:center;margin-bottom:12px;font-weight:800;font-size:24px;letter-spacing:2px}.brand img{width:52px;height:52px;object-fit:contain;background:white;border-radius:8px}main{max-width:1120px;margin:36px auto;padding:0 22px}h1{font-size:clamp(2rem,5vw,3.4rem);line-height:1.13;letter-spacing:-.035em}h2{margin-top:2em;line-height:1.25}h3{line-height:1.35}p,li,td,code{overflow-wrap:anywhere}p{max-width:80ch}.lead{font-size:1.22rem;color:#395765}.eyebrow{text-transform:uppercase;letter-spacing:.15em;font-size:.8rem;font-weight:700}.card,.step,.panel{background:white;border:1px solid #cbd9df;border-radius:12px;padding:24px;margin:20px 0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,260px),1fr));gap:20px}.grid .card{margin:0}.actions{display:flex;flex-wrap:wrap;gap:12px;margin:22px 0}.button{display:inline-block;background:#14536a;color:white;padding:10px 18px;border-radius:7px;text-decoration:none;font-weight:650}.secondary{background:white;border:1px solid #14536a;color:#14536a}.note{border-left:4px solid #af6b22;padding:12px 18px;background:#fff7eb}pre{background:#102d3b;color:#f4fbff;padding:20px;border-radius:8px;overflow-x:auto;white-space:pre-wrap}code{font-family:ui-monospace,monospace}.field{font-weight:700;color:#234a75}.value{font-family:ui-monospace,monospace;color:#17624e;background:#edf6f1;padding:1px 4px}.control{font-weight:750;color:#234a75}.state{font-style:italic}.table-wrap{overflow-x:auto}table{border-collapse:collapse;width:100%;background:white;font-size:.95rem}th,td{border:1px solid #b7cbd4;padding:12px;text-align:left;vertical-align:top}th{background:#eaf1f5}figure{margin:20px 0}figure img{display:block;max-width:100%;height:auto;border:1px solid #b7cbd4;border-radius:6px}figcaption{font-size:.85rem;color:#45616c;margin-top:8px}.step{border-top:4px solid #24657a}.step h3{margin-top:0}.step-number{display:inline-block;padding:3px 12px;border-radius:25px;background:#e6f0f4;margin-right:8px}.input-row{padding:14px 0;border-bottom:1px solid #d6e1e6}.input-row strong{display:block}.input-row p{margin:4px 0}.flow{display:flex;flex-wrap:wrap;gap:10px;padding:0;list-style:none}.flow li{background:#e2eef2;padding:10px 15px;border-radius:6px}footer{max-width:1120px;margin:50px auto;padding:24px 22px;border-top:1px solid #c3d3da;font-size:.9rem}.skip{position:absolute;left:-10000px}.skip:focus{left:20px;top:8px;background:white;padding:12px;z-index:10}a:focus-visible{outline:3px solid #ad671b;outline-offset:4px}summary{cursor:pointer;font-weight:700}section{scroll-margin-top:20px}@media(max-width:600px){main{margin-top:25px;padding:0 16px}.card,.step,.panel{padding:18px}nav{font-size:.9rem}.actions{flex-direction:column}.button{text-align:center}th,td{padding:8px}.lead{font-size:1.08rem}}'''
(OUT/'assets/site.css').write_text(css);shutil.copy2(ROOT/'ui/assets/anubis-logo.png',OUT/'assets/anubis-logo.png')
for name in ['LICENSE','NOTICE']:shutil.copy2(ROOT/name,OUT/'downloads'/name)
def inline(t):
 return re.sub(r'\[\[(field|value|control|state):(.*?)\]\]',lambda m:f'<span class="{m[1]}">{m[2]}</span>',escape(str(t)),flags=re.S)
def page(name,title,body):
 nav=''.join(f'<a href="{p}"'+(' aria-current="page"' if name==p else '')+f'>{label}</a>' for p,label in [('index.html','Overview'),('getting-started.html','Getting Started'),('methodology.html','Methodology'),('scenarios.html','Example Scenarios'),('playbooks.html','Playbooks')])
 (OUT/name).write_text(f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{escape(title)} — Anubis AI Factory workload sizing documentation"><title>{escape(title)} | Anubis</title><link rel="icon" href="assets/anubis-logo.png"><link rel="stylesheet" href="assets/site.css"></head><body><a class="skip" href="#content">Skip to content</a><header><div class="brand"><img src="assets/anubis-logo.png" alt="Anubis weighing a workload">ANUBIS</div><nav aria-label="Documentation">{nav}<a href="{REPO}">GitHub ↗</a></nav></header><main id="content">{body}</main><footer>Created by Traiano Giuseppe Welcome · <a href="mailto:traiano@gmail.com">traiano@gmail.com</a><br>Free for personal and commercial use under <a href="downloads/LICENSE">Apache License 2.0</a>. <a href="downloads/NOTICE">Attribution and third-party notices</a> · <a href="{REPO}/blob/main/docs/licensing.md">Licensing guide</a><br>Documentation accompanies the Anubis planning MVP. Example capacities are explicit planning assumptions.</footer></body></html>''')
def download(src):
 p=ROOT/src;assert p.exists(),p;shutil.copy2(p,OUT/'downloads'/p.name);return 'downloads/'+p.name
def picture(src,alt):
 p=Path(src);dest=OUT/'assets'/p.parent.name/p.name;dest.parent.mkdir(exist_ok=True);shutil.copy2(ROOT/p,dest);url=dest.relative_to(OUT).as_posix()
 return f'<figure><a href="{url}" aria-label="Open full-size image: {escape(alt)}"><img src="{url}" alt="{escape(alt)}" loading="lazy"></a><figcaption>{escape(alt)}. Tap or click the image to view it at full size.</figcaption></figure>'
def counts(s):
 g=s['expected_gpu_counts'];return f'<div class="table-wrap"><table><caption>Expected planning result</caption><thead><tr><th>B300 workload GPUs</th><th>B200 workload GPUs</th><th>H200 workload GPUs</th><th>Selected B300 factory size</th></tr></thead><tbody><tr><td>{g["HGX_B300"]}</td><td>{g["HGX_B200"]}</td><td>{g["HGX_H200"]}</td><td>{s["expected_factory_gpus"]}</td></tr></tbody></table></div>'
def formats(s):
 stem=s['id']+'_'+s['name'].replace(' ','_')+'_Playbook';pdf=download('docs/playbooks/'+stem+'.pdf');word=download('docs/playbooks/'+stem+'.docx')
 return f'<div class="actions"><a class="button" href="{s["id"].lower()}.html">Read online</a><a class="button secondary" href="{pdf}">View PDF</a><a class="button secondary" href="{word}" download>Download editable Word version (.docx)</a></div>'
page('index.html','Weigh the workload. Inform the design.', '''<p class="eyebrow">AI Factory workload sizing</p><h1>Weigh the workload.<br>Inform the design.</h1><p class="lead">Turn an application description into estimated GPU requirements and a reviewable handoff for your AI Factory design tool or process.</p><div class="actions"><a class="button" href="getting-started.html">Get your first estimate</a><a class="button secondary" href="playbooks.html">Explore worked examples</a></div><div class="grid"><section class="card"><h2>Understand the application</h2><p>Identify the activities, where they run, their demand and the measurements needed to size them.</p></section><section class="card"><h2>Compare GPU requirements</h2><p>Review B300, B200 and H200 workload estimates with their assumptions and sensitivity.</p></section><section class="card"><h2>Move into design</h2><p>Prepare design inputs, retain unresolved requirements and save the engagement for later retrieval.</p></section></div><h2>Start without a model provider</h2><p>The sizing engine is deterministic. The manual workflow needs no LLM account or GPU hardware. An optional Copilot helps interpret descriptions for your review and explain saved results without changing their calculations.</p><p class="note">These are planning estimates. Specialist workloads need applicable reference-capacity inputs. Missing storage or network measurements remain visible rather than becoming invented requirements.</p>''')
install=download('docs/macos-installation-guide.txt');copilot=download('docs/copilot-operation.txt')
page('getting-started.html','Your first AI Factory workload estimate',f'''<p class="eyebrow">Getting Started · macOS</p><h1>Your first AI Factory workload estimate</h1><p class="lead">Install Anubis, sign in and follow a complete example from workload description to saved design handoff.</p><p>The evaluated installation is macOS on Apple Silicon. This is a local application built from source. Linux guidance is deferred and Intel Macs have not been qualified. You need an internet connection for installation, but no GPU or LLM service for the manual walkthrough.</p><ol class="flow"><li>1. Install</li><li>2. Sign in</li><li>3. Describe demand</li><li>4. Calculate</li><li>5. Handoff and save</li></ol><h2>1. Install the tools and obtain Anubis</h2><p>Install Apple’s command-line tools if needed, and follow the <a href="https://docs.brew.sh/Installation">official Homebrew installation instructions</a>.</p><pre><code>xcode-select --install
brew install cmake node openssl@3 sqlite python
git clone https://github.com/engeneon/anubis-blue.git
cd anubis-blue</code></pre><h2>2. Build and check the application</h2><p>Run each command in the repository folder. Wait for it to finish successfully before continuing. Do not run the build or application with sudo.</p><pre><code>cmake --preset local -DCMAKE_PREFIX_PATH="$(brew --prefix openssl@3);$(brew --prefix sqlite)"
cmake --build --preset local -j4
npm ci --ignore-scripts
npm run build
ctest --test-dir build --output-on-failure</code></pre><p>If a command fails, resolve the reported error before proceeding. See the <a href="{install}">complete installation and recovery guide</a> for prerequisites and troubleshooting.</p><h2>3. Launch and get your access token</h2><pre><code>python3 deploy/local/run.py</code></pre><p>Leave this Terminal running. Open <a href="http://127.0.0.1:8787">http://127.0.0.1:8787</a> on the Mac running Anubis. In a second Terminal, change to the same repository folder and run:</p><pre><code>open -a TextEdit .anubis/identities.json</code></pre><p>Find the entry whose <code>id</code> is <code>local-owner</code>. Copy only the text inside the quotation marks after <code>token</code>. Paste it into <strong>Access token</strong>, then select <strong>Open workspace</strong>. Close the editor without changing the file.</p><p class="note">Keep the token private. It is generated on first launch and is different from a model-provider API key. Never put either credential in a workload description or screenshot.</p><h2>4. Follow the Nacre customer example</h2><p>Nacre keeps its main AI service outside this factory and explicitly adds a local continuity fallback. The example teaches placement boundaries and produces an estimated <strong>8 B300, 8 B200 or 8 H200 workload GPUs</strong>. The selected factory configuration is separately anchored at <strong>256 GPUs</strong>.</p><div class="actions"><a class="button" href="s13.html#manual">Follow the manual walkthrough</a><a class="button secondary" href="s13.html#inputs">Review all example inputs</a></div><p>The walkthrough includes exact values, architecture diagrams and screenshots. Continue through <strong>Calculate estimate</strong>, <strong>Prepare projection</strong> and <strong>Explain this to me</strong>. Use the deterministic explanation option for this first run.</p><h2>5. Complete and retrieve the engagement</h2><p>Download the design intake and companion specification. Review outstanding measurements, confirm delivery and select <strong>Complete engagement</strong>. Use <strong>Cases</strong> and <strong>Saved deliverables</strong> to return to the saved results.</p><p>Stop the server with Control C. Restart with <code>python3 deploy/local/run.py</code>. Saved cases persist in <code>.anubis/anubis.sqlite</code> and the access token remains in <code>.anubis/identities.json</code>. Preserve and back up this folder. Text not yet submitted to the server must not be assumed saved.</p><h2>Optional: add Copilot</h2><p>Configure an approved connection under <strong>AI connections</strong> and test it. Provider credentials stay on the backend. Model-service fees may apply. Follow the <a href="{copilot}">Copilot configuration guide</a>, then try the assisted route in a playbook. Review proposed facts before applying them.</p>''')
method=download('docs/Anubis_Workload_Sizing_Methodology.pdf');architecture=download('docs/Anubis_Technical_Architecture.pdf')
page('methodology.html','How Anubis turns demand into requirements',f'''<p class="eyebrow">Methodology overview</p><h1>From application demand to design requirements</h1><p class="lead">A transparent planning process with explicit inputs, deterministic calculations and traceable assumptions.</p><ol><li><strong>Describe the application.</strong> Identify activities and architecture patterns, then confirm what runs inside and outside the factory.</li><li><strong>Characterise demand.</strong> Capture peak work rates, model-call expansion and work size. Identify overlap, isolation and supporting services.</li><li><strong>Select a supported sizing method.</strong> Use analytical dense language-model sizing or an explicitly accepted reference capacity for independently repeatable GPU groups.</li><li><strong>Check feasibility and compare platforms.</strong> Apply memory constraints, whole-node granularity and sensitivity assumptions to the B300, B200 and H200 options.</li><li><strong>Prepare the design requirements.</strong> Distinguish workload GPU counts from factory deployment anchors. Retain host, storage and network requirements, plus outstanding measurements.</li></ol><h2>Reference capacity for specialist work</h2><p>For independently repeatable groups, the base number of groups is peak work rate divided by capacity per group, rounded up. Complete groups and supported node sizes are retained. Each GPU platform needs its own applicable capacity assumption, and per-GPU memory must fit. This does not infer linear scaling of a single larger model or simulation.</p><h2>Uncertainty stays visible</h2><p>The ±10/20/30% sensitivity choices explore changes in planning assumptions. They are not statistical confidence intervals. Missing measurements are not zero demand, and fictional example capacities are not hardware benchmarks.</p><h2>Networks and storage</h2><p>Anubis distinguishes GPU east-west communication, north-south traffic, customer-datacenter connectivity and a physically dedicated storage network. Required measurements and unresolved quantities remain explicit. A corpus outside the factory is not automatically a local copy or an initial transfer.</p><h2>Copilot supports the consultant</h2><p>Proposed workload facts require review. Saved-result explanations interpret authoritative calculation facts and cannot modify sizing or the design handoff. Qualitative model prose remains interpretation.</p><div class="actions"><a class="button" href="{method}">Read the full methodology PDF</a><a class="button secondary" href="{architecture}">Read the technical architecture PDF</a></div><p>This page is an introductory summary. The linked documents include the implementation addendum and explain the model’s scope in more detail.</p>''')
cards=[]
for s in scenarios:
 cards.append(f'<section class="card" id="{s["id"].lower()}"><p class="eyebrow">{s["id"]}</p><h2>{escape(s["name"])}</h2><p>{escape(s["original_story"])}</p>{counts(s)}<details><summary>Planning assumptions and acceptance criteria</summary><p>{escape(s["planning_assumptions"])}</p><pre>{escape(json.dumps(s["success_criteria"],indent=2))}</pre></details>'+ (f'<p><a href="{s["id"].lower()}.html">Open the complete illustrated playbook →</a></p>' if s in selected else '')+'</section>')
page('scenarios.html','Sixteen worked customer scenarios','<p class="eyebrow">Example Scenarios</p><h1>Explore a workload like yours</h1><p class="lead">Sixteen fictional business scenarios with explicit planning inputs and expected GPU comparisons.</p><p>These are reproducible demonstrations, not customer deployments or measured performance claims. Four include complete manual and Copilot-assisted playbooks.</p>'+''.join(cards)+f'<p><a href="{REPO}/blob/main/docs/gpu-complete-scenarios.md">View the complete input catalogue</a></p>')
page('playbooks.html','Step-by-step customer playbooks','<p class="eyebrow">Playbooks</p><h1>Follow a workload from description to handoff</h1><p class="lead">Read on any screen, view the printable PDF, or download an editable Word copy.</p><p>Each guide includes token setup, exact input values, architecture diagrams, manual and assisted routes, GPU comparisons, explanation and saved completion.</p>'+''.join(f'<section class="card"><p class="eyebrow">{s["id"]}</p><h2>{escape(s["name"])}</h2>{counts(s)}{formats(s)}</section>' for s in selected))
for s in selected:
 folder=ROOT/'deliverables/complete-playbooks'/s['id'];register=json.loads((folder/'input-register.json').read_text());routes={m:json.loads((folder/(m+'.json')).read_text()) for m in ['manual','assisted']}
 body=f'<p class="eyebrow">{s["id"]} · Customer playbook</p><h1>{escape(s["name"])}</h1><p class="lead">From workload description to a saved GPU estimate and design handoff.</p>{formats(s)}<h2>Customer scenario</h2><p>{escape(s["original_story"])}</p><p>{escape(s["planning_assumptions"])}</p><section id="inputs"><h2>Inputs you will use</h2><p>Use these values for the worked example. Blank fields remain unknown. Field names are bold blue, entered values are green monospace, and actions are bold.</p>'
 body+=''.join(f'<div class="input-row"><strong>{escape(r["id"])} · {escape(r["scope"])} · <span class="field">{escape(r["field"])}</span></strong><p><span class="value">{escape(r["value"])}</span></p><small>{escape(r["basis"])}</small></div>' for r in register)+'</section><p>Displayed engine defaults: BF16 weights and KV cache, context 8192 tokens, 32 concurrent sequences, 8 GB workspace, compute efficiency 0.35 and memory efficiency 0.50. Host provisions are 256 GB RAM, 3840 GB local disk and 16 CPU cores per workload GPU. A blank growth horizon uses 365 days. Reference sizing does not use text-token equations.</p><h2>Your application map</h2>'
 for m in routes['manual']['maps']:body+=picture(m['image'],m['name']+' architecture and measurement points')
 body+=counts(s)+'<p class="note">The workload count and factory size serve different purposes. Spare compute does not establish a validated tenant limit. Unresolved network and shared-storage requirements remain in the companion specification.</p><div class="actions"><a class="button" href="#manual">Manual route</a><a class="button secondary" href="#assisted">Copilot-assisted route</a><a class="button secondary" href="#parameters">How to obtain the inputs</a></div><p>New installation? Complete <a href="getting-started.html">Getting Started</a> first. Configure a tested connection before following the assisted route.</p>'
 for mode,title in [('manual','Manual route'),('assisted','Copilot-assisted route')]:
  assert routes[mode]['validated'];body+=f'<section id="{mode}"><h2>{title}</h2><p>Use a separate engagement for each route. Both use the same workload assumptions. Follow the steps in order.</p>'
  for i,st in enumerate(routes[mode]['steps'],1):body+=f'<article class="step"><h3><span class="step-number">Step {i}</span></h3><p>{inline(st["text"])}</p>'+picture(st['image'],f'{s["name"]}, {title.lower()}, step {i}')+'</article>'
  body+='</section>'
 body+='<section id="parameters"><h2>How to obtain each parameter</h2>'+''.join(f'<details class="panel"><summary>{escape(r["id"])} · {escape(r["field"])}</summary><p>{escape(r["definition"])}</p><p>{escape(r["method"])}</p></details>' for r in register)+'</section><h2>Placement and saved results</h2><p><strong>Outside this AI Factory</strong> means beyond the capacity being designed. Examples include a customer GPU cluster, hosted model API, customer search cluster or existing object store. It does not necessarily mean public Internet. Source documents and a searchable index have different footprints.</p><p>Use Cases and Saved deliverables to retrieve the exact calculation, handoff and explanation. Refining assumptions requires a new calculation. The model explanation cannot change an existing result.</p>'
 page(s['id'].lower()+'.html',s['name']+' playbook',body)
class Links(HTMLParser):
 def handle_starttag(self,tag,attrs):
  for key,value in attrs:
   if key in ['href','src'] and value and not value.startswith(('http:','https:','mailto:','#')):
    target=value.split('#')[0];assert (OUT/target).exists(),target
for p in OUT.glob('*.html'):Links().feed(p.read_text())
print(f'Built and checked {len(list(OUT.glob("*.html")))} pages at {OUT}')
